/** The symbol of an icon key (bg-playlists.txt's "!icons"), the list's when it is unknown. */
inline const AlphaSymbol& of(const char* key) {
    for (const Entry& e : kAll) if (!strcmp(e.key, key)) return *e.sym;
    return list;
}

